/**
 * The meat of a grill dish as picture cards in one radio group (fieldset with role radiogroup named by its
 * legend): a picture, the name and the price per 500 g; the first checked.
 */
import { type ReactNode } from "react";
import { Box, Fieldset, Inline, Label, Legend, Radio } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { fmtMoney, tpl } from "../utils";
import type { DishOption } from "./option-chips.types";

export type MeatCardsProps = {
  name: string;
  legend: string;
  options: DishOption[];
};

export function MeatCards({ name, legend, options }: MeatCardsProps) {
  return (
    <Fieldset
      className="flex flex-col gap-2"
      role="radiogroup"
      aria-labelledby={tpl("{0}-legend", name)}
      data-slot="meat"
    >
      <Legend size="sm" className="mb-2" id={tpl("{0}-legend", name)}>
        {legend}
      </Legend>
      <Box className="grid grid-cols-2 gap-4 md:grid-cols-4">
        {(options ?? []).map((o, i) => (
          <Box key={o.id}
            className={"flex flex-col gap-2 rounded p-2 text-sm inset-ring inset-ring-border has-checked:bg-muted " +
              "has-checked:inset-ring-foreground"}
            data-slot="option"
          >
            <MediaFrame alt={o.name} ratio="4/3" />
            <Label className="flex items-center gap-2 font-medium">
              <Radio name={name} value={o.id} checked={(i === 0)} />
              <Inline>
                {o.name}
              </Inline>
            </Label>
            <Inline className="text-xs text-muted-foreground">
              {tpl("{0} · {1}", fmtMoney(o.price, o.currency), o.note)}
            </Inline>
          </Box>
        ))}
      </Box>
    </Fieldset>
  );
}
